                "blackguard": {
                    "title": "Blackguard",
                    "tipo": "json",
                    "path": "./data/blackguard.json",
                    "inlineContent": "{\n  \"name\": \"Blackguard\",\n  \"source\": \"MPMM\",\n  \"page\": 63,\n  \"otherSources\": [\n    {\n      \"source\": \"VGM\",\n      \"page\": 211\n    }\n  ],\n  \"size\": [\n    \"M\"\n  ],\n  \"type\": {\n    \"type\": \"humanoid\",\n    \"tags\": [\n      \"paladin\"\n    ]\n  },\n  \"alignment\": [\n    \"N\",\n    \"E\"\n  ],\n  \"alignmentPrefix\": \"Typically \",\n  \"ac\": [\n    {\n      \"ac\": 18,\n      \"from\": [\n        \"{@item plate armor|PHB|plate}\"\n      ]\n    }\n  ],\n  \"hp\": {\n    \"average\": 119,\n    \"formula\": \"14d8 + 56\"\n  },\n  \"speed\": {\n    \"walk\": 30\n  },\n  \"str\": 18,\n  \"dex\": 11,\n  \"con\": 18,\n  \"int\": 11,\n  \"wis\": 14,\n  \"cha\": 15,\n  \"save\": {\n    \"wis\": \"+5\",\n    \"cha\": \"+5\"\n  },\n  \"skill\": {\n    \"athletics\": \"+7\",\n    \"deception\": \"+5\",\n    \"intimidation\": \"+5\"\n  },\n  \"passive\": 12,\n  \"languages\": [\n    \"any one language (usually Common)\"\n  ],\n  \"cr\": \"8\",\n  \"spellcasting\": [\n    {\n      \"name\": \"Spellcasting\",\n      \"type\": \"spellcasting\",\n      \"headerEntries\": [\n        \"The blackguard casts one of the following spells, using Charisma as the spellcasting ability (spell save {@dc 13}):\"\n      ],\n      \"daily\": {\n        \"2e\": [\n          \"{@spell command}\",\n          \"{@spell dispel magic}\",\n          \"{@spell find steed}\"\n        ]\n      },\n      \"ability\": \"cha\",\n      \"displayAs\": \"action\"\n    }\n  ],\n  \"action\": [\n    {\n      \"name\": \"Multiattack\",\n      \"entries\": [\n        \"The blackguard makes three attacks, using Glaive, Shortbow, or both.\"\n      ]\n    },\n    {\n      \"name\": \"Glaive\",\n      \"entries\": [\n        \"{@atk mw} {@hit 7} to hit, reach 10 ft., one target. {@h}9 ({@damage 1d10 + 4}) slashing damage plus 9 ({@damage 2d8}) necrotic damage.\"\n      ]\n    },\n    {\n      \"name\": \"Shortbow\",\n      \"entries\": [\n        \"{@atk rw} {@hit 3} to hit, range 80/320 ft., one target. {@h}5 ({@damage 1d6 + 2}) piercing damage.\"\n      ]\n    },\n    {\n      \"name\": \"Dreadful Aspect (Recharges after a Short or Long Rest)\",\n      \"entries\": [\n        \"Each enemy within 30 feet of the blackguard must succeed on a {@dc 13} Wisdom saving throw or be {@condition frightened} of the blackguard for 1 minute. If a {@condition frightened} target ends its turn more than 30 feet away from the blackguard, the target can repeat the saving throw, ending the effect on itself on a success.\"\n      ]\n    }\n  ],\n  \"bonus\": [\n    {\n      \"name\": \"Smite\",\n      \"entries\": [\n        \"Immediately after the blackguard hits a target with an attack roll, the blackguard can force that target to make a {@dc 13} Constitution saving throw. On a failed save, the target suffers one of the following effects of the blackguard's choice:\"\n      ]\n    },\n    {\n      \"name\": \"Blind\",\n      \"entries\": [\n        \"The target is {@condition blinded} for 1 minute. The {@condition blinded} target can repeat the save at the end of each of its turns, ending the effect on itself on a success.\"\n      ]\n    },\n    {\n      \"name\": \"Shove\",\n      \"entries\": [\n        \"The target is pushed up to 10 feet away and knocked {@condition prone}.\"\n      ]\n    }\n  ],\n  \"environment\": [\n    \"underdark\",\n    \"urban\"\n  ],\n  \"soundClip\": {\n    \"type\": \"internal\",\n    \"path\": \"bestiary/blackguard.opus\"\n  },\n  \"attachedItems\": [\n    \"glaive|phb\",\n    \"shortbow|phb\"\n  ],\n  \"actionTags\": [\n    \"Multiattack\"\n  ],\n  \"languageTags\": [\n    \"C\",\n    \"X\"\n  ],\n  \"damageTags\": [\n    \"N\",\n    \"P\",\n    \"S\"\n  ],\n  \"spellcastingTags\": [\n    \"O\"\n  ],\n  \"miscTags\": [\n    \"MLW\",\n    \"MW\",\n    \"RCH\",\n    \"RNG\",\n    \"RW\"\n  ],\n  \"conditionInflict\": [\n    \"blinded\",\n    \"frightened\",\n    \"prone\"\n  ],\n  \"conditionInflictSpell\": [\n    \"prone\"\n  ],\n  \"savingThrowForced\": [\n    \"constitution\",\n    \"wisdom\"\n  ],\n  \"savingThrowForcedSpell\": [\n    \"wisdom\"\n  ],\n  \"hasToken\": true,\n  \"hasFluff\": true,\n  \"hasFluffImages\": true,\n  \"customToken\": \"./monster/data/blackguard/blackguard.webp\",\n  \"customArt\": \"./monster/data/blackguard/blackguard-art.webp\"\n}"
                },
