                    "inlineContent": "{\"name\":\"Boneclaw\",\"source\":\"MPMM\",\"size\":[\"L\"],\"type\":\"undead\",\"alignment\":[\"C\",\"E\"],\"ac\":[{\"ac\":16,\"from\":[\"natural armor\"]}],\"hp\":{\"average\":150,\"formula\":\"20d10 + 40\"},\"speed\":{\"walk\":40},\"str\":19,\"dex\":16,\"con\":15,\"int\":13,\"wis\":15,\"cha\":9,\"save\":{\"dex\":\"+7\",\"con\":\"+6\",\"wis\":\"+6\"},\"skill\":{\"perception\":\"+6\",\"stealth\":\"+7\"},\"resist\":[\"cold\",\"necrotic\"],\"immune\":[\"poison\"],\"senses\":[\"darkvision 60 ft.\"],\"passive\":16,\"languages\":[\"Common\"],\"cr\":\"12\",\"hasToken\":true,\"hasFluffImages\":true,\"action\":[{\"name\":\"Multiattack\",\"entries\":[\"The boneclaw makes two Piercing Claw attacks.\"]},{\"name\":\"Piercing Claw (Reach 15 ft.)\",\"entries\":[\"{@atk mw} {@hit 8} to hit, reach 15 ft., one target. {@h}20 ({@damage 3d10 + 4}) piercing damage, pulls target up to 15 feet, and target is {@condition grappled} (escape {@dc 14}).\"]},{\"name\":\"Shadow Jump {@recharge 5}\",\"entries\":[\"Each creature within 5 feet must make a {@dc 14} Constitution save or take 34 ({@damage 5d12 + 2}) necrotic damage. Teleports up to 60 feet bringing one grappled creature.\"]}],\"reaction\":[{\"name\":\"Deadly Reach\",\"entries\":[\"In response to a visible enemy moving into its reach (15 ft.), makes one Piercing Claw attack; if it hits, makes a second attack.\"]}]}"
