                "night-hag-elite": {
                    "title": "Night Hag",
                    "tipo": "json",
                    "path": "./data/night-hag-elite.json",
                    "inlineContent": "{\"name\": \"Night Hag\", \"source\": \"XMM\", \"srd52\": true, \"basicRules2024\": true, \"size\": [\"M\"], \"type\": \"fiend\", \"alignment\": [\"N\", \"E\"], \"ac\": [19], \"hp\": {\"average\": 180, \"formula\": \"24d8 + 72\"}, \"speed\": {\"walk\": 30}, \"initiative\": {\"proficiency\": 1}, \"str\": 18, \"dex\": 15, \"con\": 16, \"int\": 16, \"wis\": 14, \"cha\": 16, \"skill\": {\"deception\": \"+6\", \"insight\": \"+5\", \"perception\": \"+5\", \"stealth\": \"+5\"}, \"senses\": [\"Darkvision 120 ft.\"], \"passive\": 15, \"resist\": [\"cold\", \"fire\"], \"conditionImmune\": [\"charmed\"], \"languages\": [\"Abyssal\", \"Common\", \"Infernal\", \"Primordial\"], \"cr\": \"8\", \"spellcasting\": [{\"name\": \"Coven Magic\", \"type\": \"spellcasting\", \"headerEntries\": [\"While within 30 feet of at least two hag allies, the hag can cast one of the following spells, requiring no Material components, using the spell's normal casting time, and using Intelligence as the spellcasting ability (spell save {@dc 17}): {@spell Augury|XPHB}, {@spell Find Familiar|XPHB}, {@spell Identify|XPHB}, {@spell Locate Object|XPHB}, {@spell Scrying|XPHB}, or {@spell Unseen Servant|XPHB}. The hag must finish a {@variantrule Long Rest|XPHB} before using this trait to cast that spell again.\"], \"restLong\": {\"1\": [\"{@spell Augury|XPHB}\", \"{@spell Find Familiar|XPHB}\", \"{@spell Identify|XPHB}\", \"{@spell Locate Object|XPHB}\", \"{@spell Scrying|XPHB}\", \"{@spell Unseen Servant|XPHB}\"]}, \"ability\": \"int\", \"hidden\": [\"restLong\"]}, {\"name\": \"Spellcasting\", \"type\": \"spellcasting\", \"headerEntries\": [\"The hag casts one of the following spells, requiring no Material components and using Intelligence as the spellcasting ability (spell save {@dc 17}):\"], \"will\": [\"{@spell Detect Magic|XPHB}\", \"{@spell Etherealness|XPHB}\", \"{@spell Magic Missile|XPHB} (level 4 version)\"], \"daily\": {\"2e\": [\"{@spell Phantasmal Killer|XPHB}\", \"{@spell Plane Shift|XPHB} (self only)\"]}, \"ability\": \"int\", \"displayAs\": \"action\"}, {\"name\": \"Nightmare Haunting (1/Day; Requires Soul Bag)\", \"type\": \"spellcasting\", \"headerEntries\": [\"While on the Ethereal Plane, the hag casts {@spell Dream|XPHB}, using the same spellcasting ability as Spellcasting. Only the hag can serve as the spell's messenger, and the target must be a creature the hag can see on the Material Plane. The spell fails and is wasted if the target is under the effect of the {@spell Protection from Evil and Good|XPHB} spell or within a {@spell Magic Circle|XPHB} spell.\", \"If the target takes damage from the {@spell Dream|XPHB} spell, the target's {@variantrule Hit Points|XPHB|Hit Point} maximum decreases by an amount equal to that damage. If the spell kills the target, its soul is trapped in the hag's soul bag, and the target can't be raised from the dead until its soul is released.\"], \"daily\": {\"1\": [\"{@spell Dream|XPHB}\", \"{@spell Protection from Evil and Good|XPHB}\", \"{@spell Magic Circle|XPHB}\"]}, \"ability\": \"int\", \"displayAs\": \"action\", \"hidden\": [\"daily\"]}], \"trait\": [{\"name\": \"Elite (Modo Fatal · 5 PJs nível 14)\", \"entries\": [\"Versão nivelada para cima: PV ×1,6, CA +2, ataques, salvaguardas e CDs +3, dados de dano ×1,5 e +3 de dano fixo. ND efetivo +3.\"]}, {\"name\": \"Magic Resistance\", \"entries\": [\"The hag has {@variantrule Advantage|XPHB} on saving throws against spells and other magical effects.\"]}, {\"name\": \"Soul Bag\", \"entries\": [\"The hag has a soul bag. While holding or carrying the bag, the hag can use its Nightmare Haunting action.\", \"The bag has AC 15, HP 20, and {@variantrule Resistance|XPHB} to all damage. The bag turns to dust if reduced to 0 {@variantrule Hit Points|XPHB}. If the bag is destroyed, any souls the bag is holding are released. The hag can create a new bag after 7 days.\"]}], \"action\": [{\"name\": \"Multiattack\", \"entries\": [\"The hag makes two Claw attacks.\"]}, {\"name\": \"Claw\", \"entries\": [\"{@atkr m} {@hit 10}, reach 5 ft. {@h}20 ({@damage 3d8 + 7}) Slashing damage.\"]}], \"bonus\": [{\"name\": \"Shape-Shift\", \"entries\": [\"The hag shape-shifts into a Small or Medium Humanoid, or it returns to its true form. Other than its size, its game statistics are the same in each form. Any equipment it is wearing or carrying isn't transformed.\"]}], \"environment\": [\"planar, lower\"], \"treasure\": [\"arcana\"], \"traitTags\": [\"Magic Resistance\"], \"senseTags\": [\"SD\"], \"actionTags\": [\"Multiattack\"], \"languageTags\": [\"AB\", \"C\", \"I\", \"P\"], \"damageTags\": [\"S\"], \"damageTagsSpell\": [\"O\", \"Y\"], \"spellcastingTags\": [\"O\"], \"miscTags\": [\"HPR\", \"MA\"], \"savingThrowForcedSpell\": [\"charisma\", \"wisdom\"], \"hasToken\": true, \"hasFluff\": true, \"hasFluffImages\": true, \"fluffEntries\": [\"Night Hag: stat block oficial XMM (5.5e), elevado ao ND 8 para o modo fatal.\"]}"
                },
