                    "path": "./data/nightwalker.json",
                    "inlineContent": "{\"name\": \"Nightwalker\", \"source\": \"MPMM\", \"size\": [\"H\"], \"type\": \"undead\", \"alignment\": [\"C\", \"E\"], \"ac\": [16], \"hp\": {\"average\": 337, \"formula\": \"25d12 + 175\"}, \"speed\": {\"walk\": 40, \"fly\": 40}, \"str\": 22, \"dex\": 19, \"con\": 24, \"int\": 6, \"wis\": 9, \"cha\": 8, \"save\": {\"con\": \"+13\"}, \"resist\": [\"acid\", \"cold\", \"fire\", \"lightning\", \"thunder\", \"bludgeoning, piercing, and slashing from nonmagical attacks\"], \"immune\": [\"necrotic\", \"poison\"], \"conditionImmune\": [\"exhaustion\", \"frightened\", \"grappled\", \"paralyzed\", \"petrified\", \"poisoned\", \"prone\", \"restrained\"], \"senses\": [\"darkvision 120 ft.\"], \"passive\": 9, \"languages\": [\"Understands Abyssal but can't speak\"], \"cr\": \"20\", \"trait\": [{\"name\": \"Annihilating Aura\", \"entries\": [\"Any creature that starts its turn within 30 feet of the nightwalker must succeed on a {@dc 21} Constitution saving throw or take 21 ({@damage 6d6}) necrotic damage. Undead are immune to this aura.\"]}, {\"name\": \"Life Eater\", \"entries\": [\"A creature dies if reduced to 0 hit points by the nightwalker and can't be revived except by a {@spell wish} spell.\"]}, {\"name\": \"Legendary Resistance (3/Day)\", \"entries\": [\"Se o nightwalker falhar numa salvaguarda, pode escolher ter sucesso.\"]}], \"action\": [{\"name\": \"Multiattack\", \"entries\": [\"The nightwalker makes two Enervating Focus attacks, and it uses Finger of Doom if available.\"]}, {\"name\": \"Enervating Focus\", \"entries\": [\"{@atk mw} {@hit 12} to hit, reach 15 ft., one target. {@h}28 ({@damage 5d8 + 6}) necrotic damage. The target must succeed on a {@dc 21} Constitution saving throw or its hit point maximum is reduced by an amount equal to the necrotic damage taken.\"]}, {\"name\": \"Finger of Doom {@recharge 6}\", \"entries\": [\"The nightwalker points at one creature it can see within 300 feet of it. The target must succeed on a {@dc 21} Wisdom saving throw or take 39 ({@damage 6d12}) necrotic damage and become {@condition frightened} and {@condition paralyzed} until the end of the nightwalker's next turn.\"]}], \"fluffEntries\": [\"**O Avatar da Aniquilação:** preso no subsolo da Death House, derrete qualquer herói empurrado para o altar. Versão FATAL: PV integrais, Legendary Resistance e 3 ações lendárias. O círculo carmim de D28 apagado reduz a Aura para 4d6.\"], \"legendary\": [{\"name\": \"Movimento (1 Ação)\", \"entries\": [\"Voa até metade do deslocamento sem provocar ataques de oportunidade.\"]}, {\"name\": \"Foco Enervante (2 Ações)\", \"entries\": [\"Faz um ataque de Enervating Focus.\"]}, {\"name\": \"Dedo da Perdição (3 Ações)\", \"entries\": [\"Usa Finger of Doom se estiver disponível.\"]}]}"
