                    "inlineContent": "{\"name\":\"Sibriex\",\"source\":\"MPMM\",\"size\":[\"H\"],\"type\":{\"type\":\"fiend\",\"tags\":[\"demon\"]},\"alignment\":[\"C\",\"E\"],\"ac\":[{\"ac\":19,\"from\":[\"natural armor\"]}],\"hp\":{\"average\":150,\"formula\":\"12d12 + 72\"},\"speed\":{\"walk\":0,\"fly\":20,\"canHover\":true},\"str\":10,\"dex\":3,\"con\":23,\"int\":25,\"wis\":24,\"cha\":25,\"save\":{\"int\":\"+13\",\"cha\":\"+13\"},\"immune\":[\"acid\",\"poison\"],\"senses\":[\"truesight 120 ft.\"],\"passive\":23,\"languages\":[\"all\",\"telepathy 120 ft.\"],\"cr\":\"18\",\"hasToken\":true,\"hasFluffImages\":true,\"spellcasting\":[{\"name\":\"Spellcasting\",\"headerEntries\":[\"Charisma (spell save {@dc 21}):\"],\"will\":[\"charm person\",\"command\",\"dispel magic\",\"hold monster\"],\"daily\":{\"3e\":[\"feeblemind\"]}}],\"trait\":[{\"name\":\"Contamination (30 ft. Difficult Terrain)\",\"entries\":[\"Ground within 30 feet is difficult terrain. Any creature starting its turn there must succeed on a {@dc 20} Constitution save or take 14 ({@damage 4d6}) acid damage.\"]},{\"name\":\"Legendary Resistance (3/Day)\",\"entries\":[\"If the sibriex fails a saving throw, it can choose to succeed instead.\"]}],\"action\":[{\"name\":\"Multiattack\",\"entries\":[\"Uses Squirt Bile once, makes two Chain attacks, and uses Warp Creature.\"]},{\"name\":\"Chain (Reach 15 ft.)\",\"entries\":[\"{@atk mw} {@hit 6} to hit, reach 15 ft., one target. {@h}20 ({@damage 2d12 + 7}) force damage.\"]},{\"name\":\"Squirt Bile\",\"entries\":[\"{@atk rs} {@hit 13} to hit, range 120 ft., one target. {@h}35 ({@damage 10d6}) acid damage.\"]},{\"name\":\"Warp Creature\",\"entries\":[\"Up to three creatures within 120 feet must make a {@dc 20} Constitution save or become {@condition poisoned} and gain 1 level of {@condition exhaustion} on each failed repeat.\"]}],\"legendary\":[{\"name\":\"Cast a Spell (1 Action)\",\"entries\":[\"Casts a spell (including Feeblemind DC 21).\"]},{\"name\":\"Warp (2 Actions)\",\"entries\":[\"Uses Warp Creature.\"]}]}"
