                "skull-lord": {
                    "title": "Skull Lord",
                    "tipo": "json",
                    "path": "./data/skull-lord.json",
                    "inlineContent": "{\"name\": \"Skull Lord\", \"source\": \"MPMM\", \"size\": [\"M\"], \"type\": \"undead\", \"alignment\": [\"L\", \"E\"], \"ac\": [{\"ac\": 18, \"from\": [\"plate\"]}], \"hp\": {\"average\": 112, \"formula\": \"15d8 + 45\"}, \"speed\": {\"walk\": 30}, \"str\": 14, \"dex\": 16, \"con\": 17, \"int\": 16, \"wis\": 15, \"cha\": 21, \"skill\": {\"perception\": \"+12\", \"stealth\": \"+8\"}, \"resist\": [\"cold\", \"necrotic\"], \"immune\": [\"poison\"], \"conditionImmune\": [\"blinded\", \"charmed\", \"deafened\", \"exhaustion\", \"frightened\", \"paralyzed\", \"poisoned\", \"stunned\"], \"senses\": [\"truesight 60 ft.\"], \"passive\": 22, \"languages\": [\"Common\", \"Abyssal\", \"Infernal\"], \"cr\": \"15\", \"spellcasting\": [{\"name\": \"Spellcasting\", \"headerEntries\": [\"The skull lord casts one of the following spells, using Charisma as the spellcasting ability (save {@dc 18}):\"], \"will\": [\"chill touch\", \"mage hand\", \"message\"], \"daily\": {\"3e\": [\"cloudkill\", \"cone of cold\", \"dispel magic\", \"fear\"], \"1e\": [\"eyebite\"]}}], \"trait\": [{\"name\": \"Legendary Resistance (3/Day)\", \"entries\": [\"If the skull lord fails a saving throw, it can choose to succeed instead.\"]}, {\"name\": \"Master of the Grave\", \"entries\": [\"While within 30 feet of the skull lord, any undead ally of the skull lord makes saving throws with advantage, and that ally regains 1d6 hit points whenever it starts its turn there.\"]}, {\"name\": \"Evasion\", \"entries\": [\"If the skull lord is subjected to an effect that allows a Dexterity saving throw to take only half damage, it instead takes no damage on a success, and half damage on a failure.\"]}], \"action\": [{\"name\": \"Multiattack\", \"entries\": [\"The skull lord makes three Bone Staff attacks.\"]}, {\"name\": \"Bone Staff\", \"entries\": [\"{@atk mw} {@hit 8} to hit, reach 5 ft., one target. {@h}7 ({@damage 1d8 + 3}) bludgeoning damage plus 21 ({@damage 6d6}) necrotic damage.\"]}, {\"name\": \"Death Ray\", \"entries\": [\"{@atk rs} {@hit 10} to hit, range 120 ft., one target. {@h}27 ({@damage 5d8 + 5}) necrotic damage.\"]}], \"legendary\": [{\"name\": \"Cast a Spell (2 Actions)\", \"entries\": [\"The skull lord casts a spell.\"]}, {\"name\": \"Death Ray (2 Actions)\", \"entries\": [\"The skull lord uses Death Ray.\"]}, {\"name\": \"Summon Undead (2 Actions)\", \"entries\": [\"Up to five skeletons or zombies appear in unoccupied spaces within 30 feet of the skull lord and remain until destroyed.\"]}], \"fluffEntries\": [\"**Galias Allester (O Sacerdote Traidor):** pai corrompido da Inquisidora Sarusanda. Lidera o Culto de Osybus e porta o Cajado de Ossos que sustenta as barreiras venenosas do corredor. Ao cair abaixo de 1/3 dos PV, a voz de Galias rompe a do Skull Lord por um instante: ele pede perdão e implora para ser destruído (veja a quest de Sarusanda).\"]}"
                },
