                    "inlineContent": "{\"name\":\"Ghast\",\"source\":\"MM\",\"size\":[\"M\"],\"type\":\"undead\",\"alignment\":[\"C\",\"E\"],\"ac\":[13],\"hp\":{\"average\":36,\"formula\":\"8d8\"},\"speed\":{\"walk\":30},\"str\":16,\"dex\":17,\"con\":10,\"int\":11,\"wis\":10,\"cha\":8,\"resist\":[\"necrotic\"],\"immune\":[\"poison\"],\"conditionImmune\":[\"charmed\",\"exhaustion\",\"poisoned\"],\"senses\":[\"darkvision 60 ft.\"],\"passive\":10,\"languages\":[\"Common\"],\"cr\":\"2\",\"hasToken\":true,\"hasFluffImages\":true,\"trait\":[{\"name\":\"Stench\",\"entries\":[\"Any creature that starts its turn within 5 feet of the ghast must succeed on a {@dc 10} Constitution saving throw or be {@condition poisoned} until the start of its next turn. On a successful saving throw, the creature is immune to the ghast's Stench for 24 hours.\"]},{\"name\":\"Turning Defiance\",\"entries\":[\"The ghast and any ghouls within 30 feet of it have advantage on saving throws against effects that turn undead.\"]}],\"action\":[{\"name\":\"Bite\",\"entries\":[\"{@atk mw} {@hit 3} to hit, reach 5 ft., one creature. {@h}12 ({@damage 2d8 + 3}) piercing damage.\"]},{\"name\":\"Claws\",\"entries\":[\"{@atk mw} {@hit 5} to hit, reach 5 ft., one target. {@h}10 ({@damage 2d6 + 3}) slashing damage. If the target is a creature other than an undead, it must succeed on a {@dc 10} Constitution saving throw or be {@condition paralyzed} for 1 minute.\"]}]}"
