        "shambling-mound": {
            "title": "Shambling Mound",
            "children": {
                "shambling-mound": {
                    "title": "Shambling Mound",
                    "tipo": "json",
                    "path": "./data/shambling-mound.json",
                    "inlineContent": "{\"name\":\"Shambling Mound\",\"source\":\"MM\",\"size\":[\"L\"],\"type\":\"plant\",\"alignment\":[\"U\"],\"ac\":[15],\"hp\":{\"average\":136,\"formula\":\"16d10 + 48\"},\"speed\":{\"walk\":20,\"swim\":20},\"str\":18,\"dex\":8,\"con\":16,\"int\":5,\"wis\":10,\"cha\":5,\"skill\":{\"stealth\":\"+2\"},\"resist\":[\"cold\",\"fire\"],\"immune\":[\"lightning\"],\"conditionImmune\":[\"blinded\",\"deafened\",\"exhaustion\"],\"senses\":[\"blindsight 60 ft. (blind beyond this radius)\"],\"passive\":10,\"languages\":[\"—\"],\"cr\":\"5\",\"hasToken\":true,\"hasFluffImages\":true,\"trait\":[{\"name\":\"Lightning Absorption\",\"entries\":[\"Whenever the shambling mound is subjected to lightning damage, it takes no damage and regains a number of hit points equal to the lightning damage dealt.\"]}],\"action\":[{\"name\":\"Multiattack\",\"entries\":[\"The shambling mound makes two slam attacks. If both attacks hit a Medium or smaller target, the target is {@condition grappled} (escape {@dc 14}), and the shambling mound uses its Engulf on it.\"]},{\"name\":\"Slam\",\"entries\":[\"{@atk mw} {@hit 7} to hit, reach 5 ft., one target. {@h}13 ({@damage 2d8 + 4}) bludgeoning damage.\"]},{\"name\":\"Engulf\",\"entries\":[\"The shambling mound engulfs a Medium or smaller creature grappled by it. The engulfed target is {@condition blinded}, {@condition restrained}, and unable to breathe, and it must succeed on a {@dc 14} Constitution saving throw at the start of each of the mound's turns or take 13 ({@damage 2d8 + 4}) bludgeoning damage. If the mound moves, the engulfed target moves with it. The mound can have only one creature engulfed at a time.\"]}]}"
                }
            }
        },
        "strahd": {
            "title": "Strahd",
            "children": {
                "strahd": {
                    "title": "Strahd von Zarovich",
                    "tipo": "json",
                    "path": "./data/strahd.json",
                    "inlineContent": "{\"name\":\"Strahd von Zarovich\",\"source\":\"CoS\",\"size\":[\"M\"],\"type\":{\"type\":\"undead\",\"tags\":[\"shapechanger\"]},\"alignment\":[\"L\",\"E\"],\"ac\":[{\"ac\":18,\"from\":[\"natural armor\"]}],\"hp\":{\"average\":144,\"formula\":\"17d8 + 68\"},\"speed\":{\"walk\":30},\"str\":18,\"dex\":18,\"con\":18,\"int\":20,\"wis\":15,\"cha\":18,\"save\":{\"dex\":\"+9\",\"wis\":\"+7\",\"cha\":\"+9\"},\"skill\":{\"arcana\":\"+15\",\"perception\":\"+12\",\"stealth\":\"+14\"},\"resist\":[\"necrotic\",\"bludgeoning, piercing, and slashing from nonmagical attacks\"],\"senses\":[\"darkvision 120 ft.\"],\"passive\":22,\"languages\":[\"Abyssal\",\"Common\",\"Draconic\",\"Elvish\",\"Giant\",\"Infernal\"],\"cr\":\"15\",\"hasToken\":true,\"hasFluffImages\":true,\"trait\":[{\"name\":\"Legendary Resistance (3/Day)\",\"entries\":[\"If Strahd fails a saving throw, he can choose to succeed instead.\"]},{\"name\":\"Regeneration\",\"entries\":[\"Strahd regains 20 hit points at the start of his turn if he has at least 1 hit point and isn't in sunlight or running water.\"]}],\"action\":[{\"name\":\"Multiattack (Vampire Form Only)\",\"entries\":[\"Strahd makes two attacks, only one of which can be a bite attack.\"]},{\"name\":\"Unarmed Strike\",\"entries\":[\"{@atk mw} {@hit 9} to hit, reach 5 ft. {@h}8 ({@damage 1d8 + 4}) slashing damage plus 14 ({@damage 4d6}) necrotic damage. If the target is a creature, Strahd can grapple it (escape {@dc 18}) instead of dealing the slashing damage.\"]},{\"name\":\"Bite\",\"entries\":[\"{@atk mw} {@hit 9} to hit, reach 5 ft. {@h}7 ({@damage 1d6 + 4}) piercing damage plus 10 ({@damage 3d6}) necrotic damage. The target's hit point maximum is reduced by an amount equal to the necrotic damage taken.\"]}],\"legendary\":[{\"name\":\"Move (1 Action)\",\"entries\":[\"Strahd moves up to his speed without provoking opportunity attacks.\"]},{\"name\":\"Unarmed Strike (1 Action)\",\"entries\":[\"Strahd makes one unarmed strike.\"]},{\"name\":\"Bite (2 Actions)\",\"entries\":[\"Strahd makes one bite attack.\"]}],\"fluffEntries\":[\"**O Lorde Desafiado:** Strahd surge no final do ritual não para matar, mas para isolar o grupo em *Haunted Zones*. Ele exige um teste de valor e só permitirá a fuga após receber dano massivo que o divirta.\"]}"
                }
            }
        },
