        "fdd": {
            "title": "Fdd",
            "children": {
                "fdd": {
                    "title": "+2 Fate Dealer's Deck",
                    "tipo": "json",
                    "path": "./data/fdd.json",
                    "inlineContent": "{\n\t\"name\": \"+2 Fate Dealer's Deck\",\n\t\"source\": \"BMT\",\n\t\"page\": 61,\n\t\"rarity\": \"very rare\",\n\t\"reqAttune\": \"by a cleric or paladin\",\n\t\"reqAttuneTags\": [\n\t\t{\n\t\t\t\"class\": \"cleric\"\n\t\t},\n\t\t{\n\t\t\t\"class\": \"paladin\"\n\t\t}\n\t],\n\t\"wondrous\": true,\n\t\"bonusSpellAttack\": \"+2\",\n\t\"bonusSpellSaveDc\": \"+2\",\n\t\"entries\": [\n\t\t\"The backs of these cards are inscribed with glyphs representing the Inner Planes, the Outer Planes, or the holy symbols of various deities. While holding this deck, you can use it as a spellcasting focus, and you gain a +2 bonus to spell attack rolls and to your spell save DC.\",\n\t\t\"In addition, while you're holding the deck, you can draw a card as an action to expend and roll one of your Hit Dice and add the deck's bonus to the number rolled. One creature you can see within 30 feet of you either takes radiant damage or regains hit points (your choice) equal to the total.\"\n\t],\n\t\"hasFluffImages\": true\n}"
                }
            }
        },
        "la-espada": {
            "title": "La Espada",
            "children": {
                "la-espada": {
                    "title": "La Espada",
                    "tipo": "html",
                    "path": "./data/la-espada.html",
                    "inlineContent": "<div class=\"item-detail active\">\n    \n    <!-- MENU DE ABAS -->\n    <div class=\"tabs-header\">\n        <button class=\"tab-btn active\" onclick=\"openTab(this, 'tab-statblock')\">Stat Block</button>\n        <!-- <button class=\"tab-btn\" onclick=\"openTab(this, 'tab-info')\">Info</button>\n        <button class=\"tab-btn\" onclick=\"openTab(this, 'tab-images')\">Imagens</button> -->\n    </div>\n\n    <!-- ABA 1: STAT BLOCK (Sua ficha principal) -->\n    <div class=\"tab-content tab-statblock active\">\n        <div class=\"page-container\">\n\n            <!-- Seção do Token -->\n            <div class=\"token-container\">\n                <img src=\"./monster/data/herald/hadar_butcher.png\" alt=\"Token do Arauto da Aniquilação\" class=\"token-image\">\n            </div>\n\n            <!-- Seção da Ficha -->\n            <div class=\"monster-card\">\n                <h1>La Espada</h1>\n                <div class=\"subtitle\">Longsword</div>\n\n                <hr class=\"red-line\">\n\n                <div class=\"stats-line\"><span class=\"label\">Dano</span> 1d8/10 cortante + 5 frio</div>\n                <div class=\"stats-line\"><span class=\"label\">Alcance</span>5 .ft</div>\n                <div class=\"stats-line\"><span class=\"label\">Versátil</span></div>\n\n                <hr class=\"red-line\">\n\n                <p><span class=\"trait-title\">Instinto Predatório do Vazio (Iniciativa).</span> O Arauto adiciona seu bônus de proficiência às suas rolagens de iniciativa.</p>\n                \n            </div>\n        </div>\n    </div>\n</div>"
                }
            }
        },
